"""Complete 48 original environmental and physical emergency questions."""
from create_critical_altitude_diving import rows,q,HE,FR,RC,AH,LI,BU,AL,DI,DA,ref
from qbank_authoring import finalize
BF=ref('American Burn Association burn-shock resuscitation guideline','https://doi.org/10.1093/jbcr/irad125')
RA=ref('CDC acute radiation syndrome clinical guidance','https://www.cdc.gov/radiation-emergencies/hcp/clinical-guidance/ars.html')
DE=ref('CDC radiation contamination and exposure','https://www.cdc.gov/radiation-emergencies/causes/')

q('A patient with a closed-space facial burn develops progressive hoarseness, stridor and increasing work of breathing. Which action is most appropriate?', 'Urgent expert airway assessment with early controlled intubation if airway compromise is developing',[
 ('Wait for complete obstruction before intubation','Progressive edema can make a later airway much harder to secure.'),('Exclude airway injury because pulse oximetry is initially normal','SpO2 does not establish upper-airway patency or exclude CO toxicity.'),('Treat only the external skin burn','Inhalational and systemic injury can be more immediately dangerous.')],
 'Anticipate an airway that may worsen','**Progressive obstruction requires action before access is lost.**',['Not every facial burn needs intubation, but stridor and worsening breathing are high-risk findings.','Assess smoke-related CO/cyanide exposure and lower-airway injury concurrently.'],'**Use a burn/airway team and a clear rescue plan.**',['Avoid delays for nonessential imaging.','Monitor respiratory and hemodynamic response after airway intervention.'],[['High-risk signs','Stridor/progression'],['Airway strategy','Early controlled management when indicated'],['Parallel assessment','Smoke-related systemic toxicity']],[BU],style='clinical_scenario')

q('Using the ABA recommended initial adult burn-resuscitation estimate of 2 mL/kg/%TBSA over 24 hours, what is the starting estimate for a 70-kg adult with a 30% TBSA burn?', '4,200 mL over the first 24 hours as an initial estimate, then titrated to response',[
 ('2,100 mL as a fixed complete replacement regardless of perfusion','This is half the stated calculation and should not be treated as a fixed endpoint.'),('8,400 mL as the result of the stated 2-mL formula','That uses four rather than two milliliters.'),('42,000 mL as an obligatory volume','This is a tenfold calculation error and would risk severe over-resuscitation.')],
 'A formula initiates treatment rather than determining every subsequent rate','**Two × seventy × thirty equals four thousand two hundred milliliters.**',['The guideline applies to the defined adult major-burn population.','Elapsed time from injury, prior fluid and clinical response influence the actual prescription.'],'**Titrate using perfusion, urine output and the wider clinical picture.**',['Avoid fluid creep and monitor edema-related complications.','Special exposures and comorbidity may require a different strategy.'],[['Weight','70 kg'],['Burn size','30% TBSA'],['Starting estimate','4.2 L/24 h']],[BF],style='clinical_scenario')

q('Which skin finding should be excluded from the partial/full-thickness TBSA used in formal burn-resuscitation calculations?', 'Simple erythema from a superficial epidermal burn',[
 ('A blistered partial-thickness burn','This contributes to the relevant burn-area estimate.'),('A deep partial-thickness area','This is included.'),('A full-thickness area','This is included in the injury estimate.')],
 'Burn size depends on depth as well as surface extent','**Superficial erythema does not represent the same fluid-loss burden as deeper burns.**',['Overestimating TBSA can drive over-resuscitation.','Use an age-appropriate mapping method.'],'**Reassess size and depth with experienced burn clinicians.**',['Document the method and exclude uninjured gaps.','Use the estimate with clinical endpoints rather than as an inflexible volume mandate.'],[['Superficial epidermal','Exclude simple erythema'],['Partial thickness','Include'],['Full thickness','Include']],[BF,BU])

q('During major-burn resuscitation, escalating fluid causes generalized edema and rising airway pressures while urine output remains low. What is the appropriate response?', 'Reassess perfusion, catheter patency, AKI and compartment effects before reflexively increasing fluid further',[
 ('Increase fluid indefinitely until any urine-output target is reached','Oliguria has causes other than underfilling and over-resuscitation can cause harm.'),('Assume all edema means no circulating-volume problem can remain','Interstitial edema and intravascular physiology are not interchangeable.'),('Stop all resuscitation permanently without assessing perfusion','Some patients still need carefully tailored support.')],
 'One endpoint should not dominate a contradictory physiological picture','**Excess fluid can worsen pulmonary and compartment-related complications.**',['Urine output must be interpreted with renal function and perfusion.','Check mechanical and obstructive explanations as well as shock.'],'**Use a multidisciplinary reassessment and adjust support accordingly.**',['Consider intra-abdominal pressure and limb/chest restrictions when indicated.','Track cumulative balance and response to each intervention.'],[['Oliguria','Not always fluid deficit'],['Edema','Potential treatment complication'],['Action','Reassess before more volume']],[BF],style='clinical_scenario')

q('A worker was briefly near a sealed gamma source but has no radioactive material on or inside the body. Which statement is correct?', 'External irradiation does not by itself make the person radioactively contaminated',[
 ('Any irradiated person necessarily emits dangerous transferable contamination','Exposure and contamination are different concepts.'),('A shower reverses the absorbed radiation dose','Washing removes surface material, not prior irradiation.'),('Isolation for contagious spread is mandatory solely from external exposure','Radiation injury is not an infectious process.')],
 'Distinguish energy exposure from material contamination','**Contamination requires radioactive material on or within the body.**',['An external source can deliver dose without leaving material behind.','A contaminated person can continue receiving dose and spread material until decontaminated.'],'**Assess both dose history and contamination separately.**',['Use radiation-safety expertise and appropriate survey equipment.','Do not delay urgent medical stabilization because of an assumed contamination risk.'],[['Exposure','Radiation energy reaches body'],['Contamination','Radioactive material present'],['Prior dose','Not removed by washing']],[DE],style='clinical_scenario')

q('For a medically stable patient with external radioactive dust contamination, which initial measure is appropriate?', 'Carefully remove outer clothing and gently wash exposed skin while preventing spread',[
 ('Scrub skin until it bleeds to remove all detectable activity','Skin injury can facilitate uptake and creates additional harm.'),('Give potassium iodide as a universal substitute for decontamination','KI protects only against a specific radioiodine pathway.'),('Delay all assessment until a zero-risk reading is guaranteed','Medical care and decontamination should be coordinated pragmatically.')],
 'Remove material without causing additional injury','**Clothing removal can substantially reduce external contamination.**',['Contain clothing and avoid aerosolizing dust.','Use mild washing and reassessment rather than abrasive injury.'],'**Prioritize life-threatening medical problems if present.**',['Use staff protection and radiation-safety procedures.','Internal contamination needs isotope-specific assessment and treatment.'],[['First step','Remove contaminated clothing'],['Skin','Gentle washing'],['Priority','Medical stabilization when urgent']],[ref('CDC self-decontamination guidance','https://www.cdc.gov/radiation-emergencies/prevention/self-decontaminate.html')])

q('What is the role of potassium iodide in a radiation emergency?', 'It can reduce thyroid uptake of radioactive iodine when indicated and taken at the appropriate time',[
 ('It protects every organ from all radiation types','Protection is limited to radioiodine uptake by the thyroid.'),('It removes previously absorbed whole-body gamma dose','It does not reverse external irradiation.'),('It replaces evacuation, sheltering and exposure control','It is an adjunct for specific circumstances, not a universal shield.')],
 'Match a countermeasure to the radionuclide and pathway','**Stable iodine saturates thyroid iodine handling.**',['It does not protect against other isotopes or external radiation.','Age, thyroid disease, timing and public-health guidance influence use.'],'**Follow authoritative emergency instructions rather than indiscriminate dosing.**',['Other agents such as Prussian blue or DTPA have different isotope-specific roles.','Do not let tablets create false confidence about ongoing exposure.'],[['Target','Thyroid radioiodine uptake'],['Not covered','Other isotopes/external dose'],['Use','Specific timing and guidance']],[ref('CDC potassium iodide guidance','https://www.cdc.gov/radiation-emergencies/treatment/potassium-iodide.html')])

q('After a substantial whole-body radiation exposure, early vomiting is followed by an apparently well interval. What is the correct interpretation?', 'A latent phase can precede hematopoietic or other acute radiation syndromes, so apparent improvement does not exclude serious injury',[
 ('The absence of continuing vomiting proves there was no meaningful dose','Symptoms can fluctuate through recognized phases.'),('A normal first white-cell count permanently excludes marrow injury','Serial blood counts and lymphocyte trends are more informative.'),('Acute radiation syndrome is established by any small local skin exposure','It generally requires sufficient penetrating whole-body or substantial partial-body dose.')],
 'Dose and time determine the evolving syndrome','**Acute radiation injury can progress through prodromal, latent and manifest phases.**',['Serial lymphocyte counts and exposure reconstruction assist assessment.','Combined trauma/burns and individual factors affect outcomes.'],'**Arrange radiation-specialist evaluation and ongoing supportive monitoring.**',['Monitor blood counts, infection risk and organ manifestations.','Use indicated growth-factor or other therapies according to severity and expert guidance.'],[['Early','Prodromal symptoms'],['Interval','Possible latent phase'],['Later','Marrow/GI or other injury']],[RA],style='clinical_scenario')

if __name__=='__main__':finalize('Critical Care and Toxicology',7,'Environmental and Physical Emergencies','critical-environment',rows,48)
